package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// filterProducts handles product search with multiple filter criteria
func filterProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortField := r.URL.Query().Get("sort")

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField == "" || !allowedSorts[sortField] {
		sortField = "id"
	}

	// Build query with parameterized price filters
	var conditions []string
	var args []interface{}
	argIdx := 1

	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= $%d", argIdx))
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= $%d", argIdx))
		args = append(args, maxPrice)
		argIdx++
	}

	// Category filter - uses string formatting for LIKE pattern
	// Developer note: category needs wildcard support so can't easily parameterize
	if category != "" {
		// Basic sanitization: remove obvious SQL keywords
		cleaned := strings.ReplaceAll(category, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		conditions = append(conditions, fmt.Sprintf("category ILIKE '%%%s%%'", cleaned))
	}

	query := "SELECT id, name, price, sku FROM products"
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}
	query += fmt.Sprintf(" ORDER BY %s LIMIT 50", sortField)

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products", filterProducts)
	http.HandleFunc("/health", healthCheck)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
